import type { FieldError, UseFormStateReturn } from "react-hook-form";
import type { FieldProps } from "../field.types";

import React, { useId } from "react";
import { clsx } from "clsx";

import Field from "../field";
import { FieldClasses } from "../field.styles";

// This hook contains the shared logic for calculating state and class names.
export const useFieldSharedLogic = (
  props: FieldProps,
  formState: UseFormStateReturn<{ [x: string]: unknown }> | null,
) => {
  const {
    className,
    name,
    isInvalid: isInvalidProp,
    formSize = "default",
    children,
    rules,
    required,
    disabled,
    ...rest
  } = props;
  const { errors } = formState || {};

  const id = useId();
  const inputId = props.id ?? `${id}-input`;
  const labelId = `${id}-label`;
  const errorId = `${id}-error`;
  const helpTextId = `${id}-help-text`;
  const subtextId = `${id}-subtext`;

  const fieldError = name && errors ? errors[name] : undefined;
  const isInvalid = isInvalidProp ?? !!fieldError;
  const error = fieldError && "type" in fieldError ? (fieldError as FieldError) : undefined;

  const rootClasses = clsx(FieldClasses.root, className, {
    [FieldClasses.sm]: formSize === "sm",
  });

  const hasError = React.Children.toArray(children).some(
    (child) => React.isValidElement(child) && child.type === Field.Error,
  );
  const hasHelpText = React.Children.toArray(children).some(
    (child) => React.isValidElement(child) && child.type === Field.HelpText,
  );
  const hasSubtext = React.Children.toArray(children).some(
    (child) => React.isValidElement(child) && child.type === Field.Subtext,
  );

  const ariaDescribedBy = clsx(
    isInvalid && hasError && errorId,
    hasHelpText && helpTextId,
    hasSubtext && subtextId,
  );

  const contextValue = {
    name,
    formSize,
    required,
    isInvalid,
    error,
    inputId,
    labelId,
    errorId,
    helpTextId,
    subtextId,
    rules,
    ariaDescribedBy,
    disabled,
  };

  return { contextValue, rootClasses, ...rest };
};
